INSERT INTO public.questions (subject, domain, skill, cb_skill_code, difficulty, difficulty_rating, passage, stem, choices, grid_in, correct, explanation, trap_choice, strategy) VALUES

('math','Algebra','Linear equations — one variable, direct solve','ALG-01','Easy',300,NULL,'If 3x + 9 = 24, what is the value of x?','{"A":"3","B":"5","C":"7","D":"11"}',false,'B','Subtract 9 from both sides: 3x = 15. Divide by 3: x = 5.','A','Isolate x step by step. Do not divide before subtracting.'),

('math','Algebra','Linear equations — word problem setup','ALG-03','Medium',500,NULL,'A store sells notebooks for $3 each and pens for $1.50 each. Maya buys a total of 10 items and spends $22.50. How many notebooks did she buy?','{"A":"3","B":"4","C":"5","D":"6"}',false,'C','Let n = notebooks, p = pens. n + p = 10 and 3n + 1.5p = 22.50. Substituting p = 10 − n gives 1.5n = 7.50, so n = 5.','D','Set up two equations — one for count, one for cost. Substitute and solve.'),

('math','Algebra','Systems of two equations — solve by elimination','ALG-06','Medium',500,NULL,'2x + 3y = 12 and 4x − 3y = 6. What is the value of x?','{"A":"1","B":"2","C":"3","D":"4"}',false,'C','Add the two equations: 6x = 18, so x = 3.','B','When y-coefficients are opposites, add the equations directly to eliminate y instantly.'),

('math','Algebra','Systems — no solution / infinite solutions','ALG-10','Hard',650,NULL,'For what value of k does the system 2x + ky = 8 and 6x + 9y = 24 have infinitely many solutions?','{"A":"2","B":"3","C":"6","D":"9"}',false,'B','Multiply the first equation by 3: 6x + 3ky = 24. To match 6x + 9y = 24, set 3k = 9, so k = 3.','D','Multiply one equation to match the other leading coefficient, then equate remaining coefficients.'),

('math','Algebra','Absolute value equations','ALG-11','Hard',650,NULL,'What are the solutions to |2x − 4| = 10?','{"A":"x = 3 and x = 7","B":"x = 7 and x = −3","C":"x = −3 and x = 3","D":"x = 7 only"}',false,'B','Two cases: 2x − 4 = 10 gives x = 7; 2x − 4 = −10 gives x = −3.','A','Always solve both the positive and negative cases of an absolute value equation.'),

('math','Advanced Math','Quadratic — factor and find roots','ADV-02','Medium',500,NULL,'What are the solutions to x² − 5x + 6 = 0?','{"A":"x = 1 and x = 6","B":"x = 2 and x = 3","C":"x = −2 and x = −3","D":"x = −1 and x = 6"}',false,'B','Factor: (x − 2)(x − 3) = 0, so x = 2 or x = 3.','C','Find two numbers that multiply to +6 and add to −5. Both roots are positive.'),

('math','Advanced Math','Exponential models — equivalent form','ADV-08','Hard',650,NULL,'A population of bacteria doubles every 3 hours. If the initial population is 500, which expression gives the population after t hours?','{"A":"500 · 2^t","B":"500 · 2^(t/3)","C":"500 · 3^(t/2)","D":"500 · (1/2)^(3t)"}',false,'B','Every 3 hours the population doubles, so the exponent is t/3. At t=3: 500·2^1 = 1000, which is double 500.','A','The doubling period goes in the denominator of the exponent. Test t=3 to verify.'),

('math','Advanced Math','Nonlinear systems — solve algebraically','ADV-12','Hard',650,NULL,'If y = x² and y = x + 6, what are the x-values of the solutions?','{"A":"x = −2 and x = 3","B":"x = 2 and x = −3","C":"x = 1 and x = 6","D":"x = −1 and x = 6"}',false,'A','Substitute: x² = x + 6 → x² − x − 6 = 0 → (x − 3)(x + 2) = 0 → x = 3 or x = −2.','B','Set expressions equal, rearrange to standard form, then factor carefully.'),

('math','PSDA','Scatterplot — read slope of line of best fit','PSA-01','Easy',300,NULL,'A line of best fit passes through (0, 4) and (5, 9). What is the slope?','{"A":"0.5","B":"1","C":"1.5","D":"2"}',false,'B','Slope = (9 − 4) / (5 − 0) = 5/5 = 1.','C','Use rise/run with two clear integer-coordinate points. Do not estimate visually.'),

('math','PSDA','Statistics — effect of adding/removing a value','PSA-06','Medium',500,NULL,'A data set has a mean of 20 and contains 5 values. If the value 50 is added, what is the new mean?','{"A":"20","B":"23","C":"25","D":"30"}',false,'C','Original sum = 20 × 5 = 100. New sum = 150. New mean = 150 / 6 = 25.','D','Compute the original sum, add the new value, divide by the new count.'),

('math','PSDA','Probability — simple (favorable/total)','PSA-08','Medium',500,NULL,'A bag contains 4 red, 5 blue, and 3 green marbles. What is the probability of selecting a marble that is NOT blue?','{"A":"5/12","B":"7/12","C":"5/7","D":"1/3"}',false,'B','Total = 12. Not blue = 7. Probability = 7/12.','A','P(not blue) = 1 − P(blue) = 1 − 5/12 = 7/12. Use the complement.'),

('math','PSDA','Percent chain — A is X% of B, B is Y% of C','PSA-13','Hard',650,NULL,'Store A revenue is 80% of Store B. Store B is 125% of Store C. Store C revenue is $200,000. What is Store A revenue?','{"A":"$160,000","B":"$200,000","C":"$250,000","D":"$320,000"}',false,'B','Store B = 1.25 × $200,000 = $250,000. Store A = 0.80 × $250,000 = $200,000.','A','Work step by step from the known value. Do not multiply all percentages at once.'),

('math','Geometry & Trig','Right triangle — SOH-CAH-TOA apply','GEO-03','Medium',500,NULL,'In a right triangle, sin(θ) = 3/5. What is cos(θ)?','{"A":"3/4","B":"4/5","C":"5/3","D":"3/5"}',false,'B','Opposite = 3, hypotenuse = 5. Adjacent = √(25 − 9) = 4. cos(θ) = 4/5.','A','Draw the triangle, label sides, apply Pythagorean theorem to find the missing side.'),

('math','Geometry & Trig','Circle equation — standard form','GEO-01','Medium',500,NULL,'What is the center and radius of (x − 3)² + (y + 2)² = 25?','{"A":"Center (3, −2), radius 5","B":"Center (−3, 2), radius 5","C":"Center (3, −2), radius 25","D":"Center (−3, 2), radius 25"}',false,'A','Standard form (x − h)² + (y − k)² = r². Here h=3, k=−2, r=5.','B','The center uses opposite signs from the equation. (x − 3) means center x = +3.'),

('math','Geometry & Trig','Area of composite shapes with algebra','GEO-08','Hard',650,NULL,'A rectangle has length (x + 2) and width (x − 1). If the area is 18 square units, what is the value of x?','{"A":"3","B":"4","C":"5","D":"6"}',false,'B','(x+2)(x−1) = 18 → x²+x−20 = 0 → (x+5)(x−4) = 0 → x = 4. Verify: 6 × 3 = 18.','A','Expand, set equal to area, solve the quadratic, verify by plugging back in.'),

('english','Craft & Structure','Vocabulary in context — common/clear word','CS-01','Easy',300,'The scientist''s findings were so ______ that even non-specialists could understand and appreciate the implications of the research.','Which word most logically completes the text?','{"A":"accessible","B":"complex","C":"theoretical","D":"ambiguous"}',false,'A','''Accessible'' means easy to understand, fitting the context. Complex and theoretical hinder understanding. Ambiguous means unclear.','B','The phrase "even non-specialists could understand" signals the blank must mean easy to grasp.'),

('english','Craft & Structure','Vocabulary in context — nuanced synonyms','CS-02','Hard',650,'Although praised for her measured approach to debate, Professor Okafor privately held ______ views — positions so extreme they would have shocked her admirers.','Which word most logically and precisely completes the text?','{"A":"strong","B":"unpopular","C":"radical","D":"personal"}',false,'C','''Radical'' means extremely departing from the norm, matching "so extreme they would have shocked." Strong is too vague, unpopular does not convey extremism, personal is irrelevant.','A','The clue is "so extreme they would have shocked." Only radical carries that level of extremism.'),

('english','Craft & Structure','Text structure — overall purpose','CS-04','Medium',500,'Urban heat islands occur when cities experience higher temperatures than surrounding rural areas, primarily because buildings and pavement absorb and retain heat. Researchers have proposed several interventions, including green roofs, increased tree canopy, and reflective road surfaces, each with varying costs and effectiveness.','What is the primary purpose of this passage?','{"A":"To argue that green roofs are the most effective solution","B":"To explain what urban heat islands are and introduce possible solutions","C":"To compare the costs of different urban cooling strategies","D":"To persuade city planners to adopt reflective road surfaces"}',false,'B','The passage defines urban heat islands and lists interventions without advocating for any. It informs rather than persuades.','C','The passage mentions costs but does not compare them. Structure is: define + list solutions.'),

('english','Information & Ideas','Main idea — explicit','II-01','Easy',300,'Monarch butterflies undertake one of the longest migrations of any insect, traveling up to 3,000 miles from Canada and the United States to overwintering sites in central Mexico. Scientists are still investigating how these butterflies navigate such vast distances using a combination of the sun''s position and Earth''s magnetic field.','Which choice best states the main idea of the text?','{"A":"Monarch butterflies use Earth''s magnetic field exclusively for navigation","B":"Monarch butterflies travel remarkable distances and use sophisticated navigation methods","C":"Scientists have fully explained how monarch butterflies navigate","D":"Monarch butterflies overwinter only in Mexico"}',false,'B','The passage covers both the distance and the navigation mechanism. A is too narrow, C contradicts still investigating, D is one detail.','A','The main idea must cover the whole passage. Eliminate answers that focus on only one detail.'),

('english','Information & Ideas','Textual evidence — which quote best supports claim','II-04','Medium',500,'Historians have long debated whether the printing press caused the Protestant Reformation or merely accelerated changes already underway. Some argue that without movable type, Luther''s 95 Theses would never have spread across Europe within weeks. Others contend that religious discontent had been building for decades before Gutenberg''s invention.','Which quotation best supports the claim that the printing press played a decisive role in spreading the Reformation?','{"A":"Historians have long debated whether the printing press caused the Protestant Reformation","B":"without movable type, Luther''s 95 Theses would never have spread across Europe within weeks","C":"religious discontent had been building for decades before Gutenberg''s invention","D":"Some argue that... Others contend that..."}',false,'B','Choice B directly states that without the press the Theses would not have spread. C weakens the claim. A sets up the debate. D is structural.','A','Find the quote that most directly states the press was decisive, not one that merely introduces the debate.'),

('english','Information & Ideas','Quantitative — data table supports which claim','II-07','Hard',650,'A researcher studied plant growth under three lighting conditions. Red light: 18 cm average. Blue light: 14 cm. White light: 22 cm.','Which claim is best supported by the data?','{"A":"Blue light inhibits all forms of plant growth","B":"White light produces the greatest average plant growth among the conditions tested","C":"Red light is more effective than white light for plant growth","D":"Plants cannot survive under blue light"}',false,'B','White light yielded 22 cm, the highest. A and D overstate since blue produced 14 cm of growth. C is contradicted by the data.','C','Stay within what the data shows. Reject extreme language and claims contradicted by the numbers.'),

('english','Standard English Conventions','Verb tense — simple past','SEC-01','Easy',300,'Last summer, the research team ______ three new species of deep-sea fish near the Pacific Rim.','Which choice completes the text with the most appropriate verb form?','{"A":"discovers","B":"will discover","C":"discovered","D":"is discovering"}',false,'C','''Last summer'' signals a completed past event, requiring simple past tense ''discovered''.','A','Time markers like last summer and yesterday always call for simple past tense.'),

('english','Standard English Conventions','Subject-verb agreement — inverted sentence','SEC-06','Hard',650,'At the center of the controversy ______ three separate allegations that the committee had not previously reviewed.','Which choice conforms to Standard English?','{"A":"is","B":"are","C":"were being","D":"has been"}',false,'B','The true subject is ''three separate allegations'' (plural), so the verb must be plural: are. The prepositional phrase is not the subject.','A','In inverted sentences identify the real subject after the verb. Allegations is plural — use are.'),

('english','Standard English Conventions','Sentence boundary — run-on correction','SEC-08','Medium',500,'The merger was approved by shareholders ______ the board of directors announced a new expansion plan the following day.','Which choice best corrects the sentence boundary error?','{"A":"shareholders, and the board","B":"shareholders the board","C":"shareholders; the board","D":"shareholders, the board"}',false,'C','A semicolon correctly joins two independent clauses. A comma alone creates a comma splice. No punctuation is a run-on.','D','A comma alone cannot join two independent clauses. Use a semicolon or a comma plus a coordinating conjunction.'),

('english','Standard English Conventions','Dangling modifier — identify and correct','SEC-12','Hard',650,'Having studied marine biology for six years, the coral reef was finally mapped by the research team.','Which choice best corrects the dangling modifier?','{"A":"Having studied marine biology for six years, the research team finally mapped the coral reef.","B":"The coral reef was finally mapped, having studied marine biology for six years.","C":"The research team mapped the coral reef after six years, having studied marine biology.","D":"Having studied marine biology, finally the coral reef was mapped by the research team."}',false,'A','The participial phrase must be immediately followed by the noun it modifies — the research team.','C','Whatever noun immediately follows the opening participial phrase is what the phrase modifies.'),

('english','Standard English Conventions','Semicolon — join independent clauses','SEC-10','Medium',500,'The novel sold millions of copies worldwide ______ critics, however, found its ending deeply unsatisfying.','Which choice uses the most appropriate punctuation?','{"A":"worldwide, critics","B":"worldwide; critics","C":"worldwide: critics","D":"worldwide critics"}',false,'B','Both clauses are independent. A semicolon joins them correctly. A comma alone is a comma splice. A colon introduces rather than contrasts.','A','When however signals contrast between two complete sentences, use a semicolon before the second clause.'),

('english','Expression of Ideas','Transition — furthermore / however / therefore','EXP-01','Easy',300,'Regular exercise has been shown to improve cardiovascular health. ______, studies indicate it also enhances mood and reduces symptoms of anxiety.','Which transition most effectively connects the two sentences?','{"A":"However","B":"Therefore","C":"Furthermore","D":"In contrast"}',false,'C','''Furthermore'' signals addition — the second sentence adds another benefit. However and In contrast signal contradiction. Therefore signals a result.','B','Identify the relationship: addition (furthermore), contrast (however), result (therefore). Match accordingly.'),

('english','Expression of Ideas','Concision — remove redundant words','EXP-06','Medium',500,'The report was brief and short in length, summarizing the key findings of the two-year study.','Which choice most effectively eliminates the redundancy?','{"A":"brief and concise in nature","B":"brief","C":"short and to the point","D":"brief, short, and concise"}',false,'B','''Brief'' already means short in length. All other choices add redundant words.','A','For concision questions, the shortest answer that preserves meaning wins. In nature and in length are filler phrases.'),

('english','Expression of Ideas','Research synthesis — introduce with evidence','EXP-03','Hard',650,'A researcher wants to argue that sleep deprivation significantly impairs cognitive performance. In a study of 200 college students, those who slept fewer than 6 hours showed a 35% decrease in memory test scores compared to those who slept 8 or more hours.','Which sentence most effectively uses the data to introduce the argument?','{"A":"Sleep is important for college students who want to perform well.","B":"A study of 200 students found various differences in test performance based on sleep habits.","C":"College students who slept fewer than 6 hours scored 35% lower on memory tests, suggesting sleep deprivation substantially harms cognitive function.","D":"The researcher studied sleep and memory in college students."}',false,'C','Choice C uses the specific data point (35% lower) and connects it to the claim. A is vague, B is imprecise, D is merely descriptive.','B','Research synthesis questions need the specific data point plus the claim it supports. Vague summaries never win.');
